class Task:
    def __init__(self, task_id, execution_time, period):
        self.task_id = task_id
        self.e = execution_time
        self.p = period

class Job:
    def __init__(self, task_id, job_index, release_time, relative_deadline, period):
        self.task_id = task_id
        self.job_index = job_index
        self.release_time = release_time
        self.absolute_deadline = release_time + relative_deadline
        self.period = period

def check_job_spacing(current_job_release, next_job_release, period):
    return next_job_release >= current_job_release + period

def calculate_total_system_utilization(task_set):
    U_total = 0
    for task in task_set:
        U_total += calculate_task_utilization(task)
    return U_total

class Task:
    # ... (previous attributes)
    def __init__(self, task_id, execution_time, period, shares_per_processor=None):
        # ...
        self.u = self.e / self.p
        self.shares = shares_per_processor if shares_per_processor is not None else {}

    def assign_share(self, processor_id, share_value):
        self.shares[processor_id] = share_value

    def get_total_assigned_share(self):
        return sum(self.shares.values())

    def check_share_validity(self):
        return self.get_total_assigned_share() == self.u

class Processor:
    def __init__(self, processor_id):
        self.processor_id = processor_id
        self.assigned_tasks_shares = {}

    def assign_task_share(self, task_id, share_value):
        self.assigned_tasks_shares[task_id] = share_value

    def calculate_assigned_capacity(self):
        return sum(self.assigned_tasks_shares.values())

class Processor:
    # ... (previous methods)
    def get_available_capacity(self):
        return 1.0 - self.calculate_assigned_capacity()

def is_hrt_schedulable(system_schedule):
    for job in system_schedule.all_jobs():
        if job.completion_time > job.absolute_deadline:
            return False # Deadline missed
    return True # All deadlines met

def is_srt_schedulable(system_schedule, max_tardiness_bound):
    for job in system_schedule.all_jobs():
        if job.completion_time > job.absolute_deadline:
            tardiness = job.completion_time - job.absolute_deadline
            if tardiness > max_tardiness_bound:
                return False # Tardiness bound exceeded
    return True # All jobs meet deadlines or stay within tardiness bound

def schedule_edf_fm(ready_tasks):
    migratory_ready = [t for t in ready_tasks if t.is_migratory]
    fixed_ready = [t for t in ready_tasks if not t.is_migratory]

    if migratory_ready:
        # Schedule migratory tasks by EDF
        migratory_ready.sort(key=lambda t: t.current_job.absolute_deadline)
        return migratory_ready[0]
    elif fixed_ready:
        # Schedule fixed tasks by EDF
        fixed_ready.sort(key=lambda t: t.current_job.absolute_deadline)
        return fixed_ready[0]
    else:
        return None # No tasks to schedule

def check_nps_f_mapping_feasibility(servers, num_processors, delta_param, inflation_function):
    total_inflated_capacity = 0
    for server in servers:
        inflated_capacity = inflation_function(delta_param, server.capacity)
        total_inflated_capacity += inflated_capacity
    return total_inflated_capacity <= num_processors

def check_processor_schedulability(processor):
    # For a single processor
    return processor.calculate_assigned_capacity() <= 1.0

def check_cluster_schedulability(cluster):
    # For a cluster of processors
    return cluster.calculate_assigned_capacity() <= cluster.num_cores
